// Validation describes supported data contracts, never executes content code.
const fail=(path,message)=>{throw new Error(`Content config ${path}: ${message}`);};
const record=(value,path)=>{if(!value||typeof value!=='object'||Array.isArray(value))fail(path,'expected an object');return value;};
const list=(value,path,max=1000)=>{if(!Array.isArray(value)||value.length>max)fail(path,`expected an array of at most ${max} entries`);return value;};
const number=(value,path,min=0,max=1e6)=>{if(!Number.isFinite(value)||value<min||value>max)fail(path,`expected a finite number in ${min}..${max}`);};
const integer=(value,path,min=0,max=1000)=>{number(value,path,min,max);if(!Number.isInteger(value))fail(path,'expected an integer');};
const string=(value,path)=>{if(typeof value!=='string'||!value.length||value.length>2000)fail(path,'expected a nonempty string');};
const key=(value,path)=>{string(value,path);if(!/^[a-zA-Z][a-zA-Z0-9:_-]*$/.test(value))fail(path,'invalid stable ID');};
const ref=(value,keys,path)=>{if(!keys.has(value))fail(path,`unknown reference ${String(value)}`);};
const ids=(items,path)=>{const seen=new Set();for(const [index,item] of list(items,path).entries()){record(item,`${path}[${index}]`);key(item.id,`${path}[${index}].id`);if(seen.has(item.id))fail(path,`duplicate ID ${item.id}`);seen.add(item.id);}return seen;};
const numericRecord=(value,path)=>{if(!value||typeof value!=='object')fail(path,'expected numeric data');for(const [name,item] of Object.entries(value)){if(item&&typeof item==='object')numericRecord(item,`${path}.${name}`);else number(item,`${path}.${name}`);}};
const requireKeys=(value,names,path)=>{record(value,path);for(const name of names)if(!(name in value))fail(path,`missing ${name}`);};
const statKeys=['maxHealth','attack','defense','moveSpeed','pickupRange'];
const weaponIds=new Set(['sword','arrow','orbit']);
const basicSkillIds=new Set(['barrier','pulse','lightning','storm','fireball','frostbolt']);
const superSkillIds=new Set(['domain','meteor','swords','vortex']);
const requiredUpgradeIds=["sword","arrow","barrier","power","rapid","multishot","orbit","pulse","lightning","speed","magnet","vitality","toughness","regen","arrowPower","arrowRetention","arrowReach","orbitPower","orbitRadius","swordEnergy","swordMastery","arrowRune","pulseMastery","lightningMastery","storm","fireball","frostbolt"];
const requiredEndlessIds=["endlessPower","endlessToughness","endlessVitality","endlessRegen"];
const effectKeys=new Set(['damageBonus','attackRateBonus','projectileCount','moveSpeedBonus','pickupRangeBonus','maxHealth','heal','defense','healthRegen','baseDamageBonus','damageRetention','maxTargets','radius','intervalReduction','cooldownReduction','chainTargets']);
const branchIds={sword:new Set(['sweep','heavy']),arrow:new Set(['pierce','ricochet']),pulse:new Set(['echoes','control']),lightning:new Set(['chain','focus']),domain:new Set(['binding','erosion'])};
function definitions(value,allowed,path){record(value,path);for(const id of allowed)if(!value[id])fail(path,`missing supported definition ${id}`);for(const [id,item] of Object.entries(value)){ref(id,allowed,path);record(item,`${path}.${id}`);if(item.id!==id)fail(`${path}.${id}`,'key and id must match');string(item.name,`${path}.${id}.name`);for(const field of ['icon','color','category','binding','activation','tier','source'])string(item[field],`${path}.${id}.${field}`);if(allowed===weaponIds&&item.attackId!==id)fail(`${path}.${id}.attackId`,'unknown weapon execution path');integer(item.initialRank,`${path}.${id}.initialRank`);integer(item.maxBaseRank,`${path}.${id}.maxBaseRank`,1);if(item.initialRank>item.maxBaseRank)fail(`${path}.${id}`,'initial rank exceeds maximum');}}

