function validateLevels(rows,max,path,branch){list(rows,path,100);if(rows.length!==max)fail(path,'one entry per super rank is required');rows.forEach((row,index)=>{record(row,`${path}[${index}]`);const kind=branch?'domain':path.split('.').at(-1);const fields={meteor:['cooldown','damage','radius','count'],swords:['cooldown','damage','count','interval'],vortex:['cooldown','damage','radius','duration','interval','pull'],domain:['cooldown','damage','impactDamage','radius','duration','interval','slow',...(branch==='binding'?['root']:['linger'])]}[kind];requireKeys(row,fields,`${path}[${index}]`);if(row.level!==index+1)fail(path,'levels must be consecutive');if(branch!==undefined&&row.branch!==branch)fail(path,'branch mismatch');const values={...row};delete values.branch;numericRecord(values,`${path}[${index}]`);number(row.cooldown,`${path}[${index}].cooldown`,.001);if(row.count!==undefined)integer(row.count,`${path}[${index}].count`,1,64);if(row.radius!==undefined)number(row.radius,`${path}[${index}].radius`,.001);if(row.duration!==undefined)number(row.duration,`${path}[${index}].duration`,.001);if(row.interval!==undefined)number(row.interval,`${path}[${index}].interval`,.001);});}
